/** The raw fixture bundle (read-only; parse it with {@link parseFixtureDomain}). */
export const LENS_FIXTURE: { objects: unknown[]; x_lens_fixture: { techniques: string[] } } =
  FIXTURE_BUNDLE as unknown as { objects: unknown[]; x_lens_fixture: { techniques: string[] } };

/** Parse the fixture with the production parser. A fresh Domain on every call. */
export function parseFixtureDomain(): Domain {
  const parser = new DataService(null as unknown as HttpClient) as unknown as {
    parseBundle(bundle: unknown, name?: string): Domain;
  };
  return parser.parseBundle(LENS_FIXTURE, 'Enterprise ATT&CK');
}

/** 32-bit FNV-1a: tiny, stable across engines, good enough to spread counts. */
export function fnv1a(text: string): number {
  let h = 0x811c9dc5;
  for (let i = 0; i < text.length; i++) {
    h ^= text.charCodeAt(i);
    h = Math.imul(h, 0x01000193) >>> 0;
  }
  return h >>> 0;
}

/**
 * "Dark" techniques: the fixture techniques that have no ATT&CK mitigation. The
 * stubs give them no external signal of any kind either, so the fixture always
 * contains wholly undefended techniques (critical-risk, KEV-gap and
 * dim-uncovered paths are exercised instead of being vacuously empty).
 */
export const DARK_TECHNIQUES: ReadonlySet<string> = (() => {
  type StixObject = { type: string; id: string; relationship_type?: string; target_ref?: string; revoked?: boolean;
    external_references?: Array<{ source_name: string; external_id?: string }> };
  const objects = LENS_FIXTURE.objects as StixObject[];
  const mitigated = new Set(objects.filter(o => o.relationship_type === 'mitigates').map(o => o.target_ref));
  return new Set(objects
    .filter(o => o.type === 'attack-pattern' && !o.revoked && !mitigated.has(o.id))
    .map(o => o.external_references?.find(r => r.source_name === 'mitre-attack')?.external_id ?? '')
    .filter(Boolean));
})();

/**
 * Deterministic per-technique count for one enrichment source: 0 for about 40%
 * of techniques (and always 0 for {@link DARK_TECHNIQUES}), otherwise 1..6.
 * Different sources hash independently, so the lenses disagree with each other
 * the way real data does.
 */
export function signal(source: string, attackId: string): number {
  if (DARK_TECHNIQUES.has(attackId)) return 0;
  const h = fnv1a(`${source}|${attackId}`);
  return h % 10 < 4 ? 0 : ((h >>> 8) % 6) + 1;
}

/** Deterministic EPSS probability in [0, 1) for a synthetic CVE id, skewed low like real EPSS. */
export function epssFor(cveId: string): number {
  const u = (fnv1a(`epss|${cveId}`) % 10000) / 10000;
  return Math.round(u * u * u * 1e6) / 1e6;
}

/** Synthetic CVE ids for a technique; the count is `signal('cve', id)`. */
export function cvesFor(attackId: string): string[] {
  const n = signal('cve', attackId);
  const digits = attackId.replace(/\D/g, '');
  return Array.from({ length: n }, (_, i) => `CVE-2024-${digits}${i}`);
}

const list = (n: number): unknown[] => Array.from({ length: n }, (_, i) => ({ i }));
const loaded = (): Observable<boolean> => of(true);

/**
 * Stubs for every enrichment source a heatmap lens, the dashboard or the
 * EnrichmentService reads. Where the app has two counts for one source (e.g.
 * CAR's bundled analytics vs its live layer count) the stub hashes them
 * separately, so a lens that switches from one to the other changes its
 * snapshot.
 */
export function signalStubProviders(): Provider[] {
  const s = signal;
  return [
    { provide: SigmaService, useValue: {
      loaded$: loaded(), loadLive: () => undefined,
      getRuleCount: (id: string) => s('sigma', id), getHeatScore: (id: string) => s('sigma', id),
    } },
    { provide: CARService, useValue: {
      loaded$: loaded(),
      getAnalytics: (id: string) => list(s('car', id)), getLiveCount: (id: string) => s('car-live', id),
    } },
    { provide: AtomicService, useValue: {
      loaded$: loaded(),
      getTestCount: (id: string) => s('atomic', id), getHeatScore: (id: string) => s('atomic-heat', id),
    } },
    { provide: D3fendService, useValue: { loaded$: loaded(), getCountermeasures: (id: string) => list(s('d3fend', id)) } },
    { provide: EngageService, useValue: { loaded$: loaded(), getActivities: (id: string) => list(s('engage', id)) } },
    { provide: CriProfileService, useValue: { loaded$: loaded(), getControlCount: (id: string) => s('cri', id) } },
    { provide: NistMappingService, useValue: { loaded$: loaded(), getControlCount: (id: string) => s('nist', id) } },
    { provide: CisControlsService, useValue: { loaded$: loaded(), getControlCount: (id: string) => s('cis', id) } },
    { provide: CsaCcmService, useValue: {
      loaded$: loaded(),
      getControlCount: (id: string) => s('csa', id), getHeatScore: (id: string) => s('csa-heat', id),
    } },
    { provide: M365ControlsService, useValue: {
      loaded$: loaded(),
      getControlCount: (id: string) => s('m365-ctl', id), getHeatScore: (id: string) => s('m365-ctl-heat', id),
    } },
    { provide: VerisService, useValue: { loaded$: loaded(), getActionsForTechnique: (id: string) => list(s('veris', id)) } },
    { provide: ElasticService, useValue: { loaded$: loaded(), getRuleCount: (id: string) => s('elastic', id) } },
    { provide: SplunkContentService, useValue: { loaded$: loaded(), getRuleCount: (id: string) => s('splunk', id) } },
    { provide: MispService, useValue: {
      loaded$: loaded(), total$: of(0), hasMisp: (id: string) => s('misp', id) > 0,
    } },
    { provide: M365DefenderService, useValue: {
      loaded$: loaded(), loadOnDemand: () => undefined, getHeatScore: (id: string) => s('m365', id),
    } },
    { provide: WazuhService, useValue: { getRulesForTechnique: (id: string) => list(s('wazuh', id)) } },
    { provide: Cve2CapecService, useValue: { loaded$: loaded(), getChainCount: (id: string) => s('kill-chain', id) } },
    { provide: PocExploitService, useValue: { loaded$: loaded(), getPocCount: (id: string) => s('poc', id) } },
    { provide: AttackCveService, useValue: {
      loaded$: loaded(),
      getCvesForTechnique: (id: string) => cvesFor(id).map(cveId => ({ cveId })),
      getKevCvesForTechnique: (id: string) => cvesFor(id).slice(0, s('kev', id)).map(cveId => ({ cveId })),
      getMappingForCve: () => undefined,
    } },
    { provide: EpssService, useValue: {
      fetchScores: (ids: string[]) => of(new Map(ids.map(id => [id, { cveId: id, epss: epssFor(id), percentile: 0, date: '' }]))),
    } },
    { provide: CveService, useValue: {
      kevTechScores$: new BehaviorSubject(kevScores()), loadKev: () => undefined, getKevEntry: () => undefined,
    } },
    { provide: AssetInventoryService, useValue: { exposureMap$: new BehaviorSubject(assetExposure()) } },
    { provide: UserLayerService, useValue: {
      activeLayer: null, changed$: of(false), maxScore: () => 1, getScore: () => 0, getGradientColor: () => null,
    } },
  ];
}

/** KEV CVE count per ATT&CK id, as CveService.kevTechScores$ publishes it. */
export function kevScores(): Map<string, number> {
  return new Map(LENS_FIXTURE.x_lens_fixture.techniques.map(id => [id, signal('kev', id)] as [string, number]).filter(([, n]) => n > 0));
}

/** Asset exposure per ATT&CK id, as AssetInventoryService.exposureMap$ publishes it. */
export function assetExposure(): Map<string, number> {
  return new Map(LENS_FIXTURE.x_lens_fixture.techniques.map(id => [id, signal('asset', id)] as [string, number]).filter(([, n]) => n > 0));
}

/** Mitigations in a stable order (by ATT&CK id), for seeding user state. */
export function sortedMitigations(domain: Domain): Mitigation[] {
  return [...domain.mitigations].sort((a, b) => a.attackId.localeCompare(b.attackId));
}

/** Implementation status seed: by mitigation position, cycling through every status and "untracked". */
export const IMPL_CYCLE = ['implemented', 'in-progress', 'planned', 'not-started', null] as const;

/**
 * Security-control seed for the `controls` lens: every 4th mitigation (by
 * ATT&CK id) is covered by an implemented control, the next one by a planned
 * control. Coverage itself is computed by the real ControlsService logic.
 */
export function fixtureControls(domain: Domain): SecurityControl[] {
  const out: SecurityControl[] = [];
  sortedMitigations(domain).forEach((m, i) => {
    if (i % 4 > 1) return;
    out.push({
      id: `ctl-${m.attackId}`,
      name: `Control for ${m.attackId}`,
      framework: 'Custom',
      controlRef: m.attackId,
      description: '',
      mitigationIds: [m.id],
      status: i % 4 === 0 ? 'implemented' : 'planned',
    });
  });
  return out;
}

/** ControlsService stub: fixed controls, real coverage computation. */
export function controlsProvider(domain: Domain): Provider {
  const real = new ControlsService();
  return {
    provide: ControlsService,
    useValue: {
      controls$: new BehaviorSubject(fixtureControls(domain)),
      computeCoverage: real.computeCoverage.bind(real),
    },
  };
}

/** Clear browser storage so services that persist user state start from defaults. */
export function resetBrowserState(): void {
  try { localStorage.clear(); } catch { /* storage unavailable: nothing to clear */ }
  try { sessionStorage.clear(); } catch { /* storage unavailable: nothing to clear */ }
}

// ─── Posture lens (P2-13, R14) ─────────────────────────────────────────────
//
// The Posture lens reads proof ages, so its snapshot would age with the real
// date. The harness pins PostureService's day to LENS_POSTURE_TODAY and dates
// its two seeded runs relative to it (one 10 days old, fresh; one 120 days
// old, past the 90-day own-run window, stale), so the snapshot never ages.
// The seed writes ONLY the validation-run store: the implementation and
// controls stores the status and controls lenses read are never touched, and
// no other lens reads runs (the frozen-hash guard in lens-snapshots.spec.ts
// proves the 33 older lenses byte-identical with the seed in place).

/** The day the lens harness pins posture to. */
export const LENS_POSTURE_TODAY = new Date('2026-10-01T00:00:00.000Z');

/** ISO timestamp `days` before LENS_POSTURE_TODAY. */
export function daysBeforeLensToday(days: number): string {
  return new Date(LENS_POSTURE_TODAY.getTime() - days * 86_400_000).toISOString();
}

/** Provides POSTURE_TODAY as the fixed LENS_POSTURE_TODAY signal. */
export function lensPostureTodayProvider(): Provider {
  return { provide: POSTURE_TODAY, useValue: ngSignal(LENS_POSTURE_TODAY) };
}

/** Ages of the two seeded runs, in days before LENS_POSTURE_TODAY. */
export const LENS_RUN_AGES = { fresh: 10, stale: 120 } as const;

/**
 * The two techniques the seeded runs land on: the first two parent
 * techniques of the fixture by ATT&CK id. Derived, never hard-coded.
 */
export function lensRunTechniques(domain: Domain): { fresh: Technique; stale: Technique } {
  const parents = domain.techniques.filter(t => !t.isSubtechnique).sort((a, b) => a.attackId.localeCompare(b.attackId));
  return { fresh: parents[0], stale: parents[1] };
}

/**
 * Seeds the two runs through ValidationService.importJson (the run store
 * only). Each passed with a named fired detection, so each is a qualifying
 * own-run proof: the 10-day one fresh, the 120-day one stale.
 */
export function seedLensRuns(validation: ValidationService, domain: Domain): void {
  const { fresh, stale } = lensRunTechniques(domain);
  const result = validation.importJson(JSON.stringify({ runs: [
    { id: 'lens-run-fresh', techniqueId: fresh.attackId, runDate: daysBeforeLensToday(LENS_RUN_AGES.fresh), status: 'passed',
      attackResult: 'executed', detectionsFired: ['sigma:lens-fresh'] },
    { id: 'lens-run-stale', techniqueId: stale.attackId, runDate: daysBeforeLensToday(LENS_RUN_AGES.stale), status: 'passed',
      attackResult: 'executed', detectionsFired: ['sigma:lens-stale'] },
  ] }));
  if (!result.ok) throw new Error(`lens harness runs not imported: ${result.error ?? 'unknown'}`);
}
